using namespace __gnu_pbds;

// Define an ordered set
typedef tree<int, null_type, less<int>, rb_tree_tag, tree_order_statistics_node_update> ordered_set;

// Define macros for convenience
#define int long long
#define f(i, a, b) for (int i = a; i < b; i++)
#define rf(i, a, b) for (int i = a; i >= b; i--)
#define vi vector<int>
#define vpii vector<pair<int, int>>
#define vvvi vector<vector<vector<int>>>
#define vvi vector<vector<int>>
#define vvpi vector<vector<pair<int, int>>>
#define vb vector<bool>
const int inf = 1e18;

int n, m, t0, t1, t2;
vvvi adj;

int dijkstra(int src, int dest, int start_time)
{
    vi dist(n + 1, inf);
    dist[src] = start_time;
    priority_queue<vi, vvi, greater<vi>> pq;
    pq.push({start_time, src});
    int dur = t2 - t1;

    while (!pq.empty())
    {
        vi curr = pq.top();
        pq.pop();
        int u = curr[1];
        int time = curr[0];
        if (time > dist[u])
            continue;

        for (vi edge : adj[u])
        {
            int v = edge[0];
            int l1 = edge[1];
            int l2 = edge[2];
            int new_time = time + l1;

            if (time >= t1 && time < t2) {
                // Call is active
                if (dur >= l2) { // take l2 route
                    new_time = time + l2;
                    dur -= l2;
                } else {
                    // take l2 route
                    if (l2 < (t2 - time) + dur + l1) {
                        new_time = time + l2;
                        dur = 0;
                    } else { // wait and take l1 route
                        new_time = time + (t2 - time) + dur + l1;
                        dur = 0;
                    }
                }
            } else if (time <= t1 && t1 < new_time) {
                // Crosses into active call period
                if (dur >= l2) { // take l2 route
                    new_time = time + l2;
                    dur -= l2;
                } else {
                    if (l2 < (t1 - time) + dur + l1) { // take l2 route
                        new_time = time + l2;
                        dur = 0;
                    } else { // wait and take l1 route
                        new_time = time + (t1 - time) + dur + l1;
                        dur = 0;
                    }
                }
            }

            if (new_time < dist[v]) { // Relaxation
                dist[v] = new_time;
                pq.push({new_time, v});
            }
        }
    }
    return dist[dest];
}

void solve()
{
    cin >> n >> m;
    cin >> t0 >> t1 >> t2;
    adj = vvvi(n + 1);
    f(i, 0, m)
    {
        int u, v, l1, l2;
        cin >> u >> v >> l1 >> l2;
        adj[u].push_back({v, l1, l2});
        adj[v].push_back({u, l1, l2});
    }

    int low = 0, high = t0;
    int ans = -1;
    // binary on how late we can start our journey to reach on time
    while (low <= high)
    {
        int mid = low + (high - low) / 2;
        if (dijkstra(1, n, mid) <= t0)
        {
            ans = mid;
            low = mid + 1;
        }
        else
        {
            high = mid - 1;
        }
    }

    cout << ans << endl;
}


